-- ── Stored Procedure ──
CREATE PROCEDURE GetUserOrders
    @UserId INT,
    @MinAmount DECIMAL(10,2) = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT o.Id, o.Amount, o.CreatedAt
    FROM Orders o
    WHERE o.UserId = @UserId AND o.Amount >= @MinAmount
    ORDER BY o.CreatedAt DESC;
END;

-- Call it:
EXEC GetUserOrders @UserId = 5, @MinAmount = 100;

