-- ── SQL: Structured, relational ──
CREATE TABLE Users (
    Id INT PRIMARY KEY,
    Name NVARCHAR(100) NOT NULL,
    Email NVARCHAR(255) UNIQUE
);

CREATE TABLE Orders (
    Id INT PRIMARY KEY,
    UserId INT FOREIGN KEY REFERENCES Users(Id),
    Amount DECIMAL(10,2)
);

-- Complex JOIN query:
SELECT u.Name, SUM(o.Amount) AS TotalSpent
FROM Users u
JOIN Orders o ON u.Id = o.UserId
GROUP BY u.Name
HAVING SUM(o.Amount) > 1000;

