-- ── DEADLOCK SCENARIO ──
-- Transaction A:                 -- Transaction B:
BEGIN TRAN;                       BEGIN TRAN;
UPDATE Accounts                   UPDATE Products
SET Balance = Balance - 100       SET Stock = Stock - 1
WHERE Id = 1;                     WHERE Id = 1;
-- holds X lock on Accounts       -- holds X lock on Products

UPDATE Products                   UPDATE Accounts
SET Stock = Stock - 1             SET Balance = Balance + 100
WHERE Id = 1;                     WHERE Id = 1;
-- WAITING for Products lock      -- WAITING for Accounts lock
-- → DEADLOCK!                    -- → SQL Server kills one!

-- ── PREVENTION: Consistent order ──
-- ALWAYS access Accounts first, then Products
BEGIN TRAN;
    UPDATE Accounts SET Balance = Balance - 100 WHERE Id = 1;
    UPDATE Products SET Stock = Stock - 1 WHERE Id = 1;
COMMIT;

